from pathlib import Path

from app.services import users

# The project's `data/` directory (repository root is two levels above this file).
DATA_DIR = Path(__file__).resolve().parents[2] / "data"


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_list_files(params: dict) -> tuple[int, dict]:
    raw = params.get("dir", "")
    if not isinstance(raw, str):
        return 400, {"error": "invalid path"}
    if raw == "":
        segments: list[str] = []
    else:
        segments = raw.split("/")
        if any(segment in ("", ".", "..") for segment in segments):
            return 400, {"error": "invalid path"}
    directory = DATA_DIR.joinpath(*segments)
    if not directory.is_dir():
        return 404, {"error": "not found"}
    files = sorted(entry.name for entry in directory.iterdir() if entry.is_file())
    return 200, {"files": files}
